using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 public static class MapDetailVerification {
  static readonly List<string> rows=new List<string>();static string Root{get{var path=Path.GetFullPath(Path.Combine(Application.dataPath,"../VerificationOutputs"));Directory.CreateDirectory(path);return path;}}
  static void Check(bool ok,string name){if(!ok)throw new Exception(name);rows.Add("PASS "+name);Debug.Log("MAP_DETAIL_PASS "+name);}
  static uint Fingerprint(Texture2D t){unchecked{uint value=2166136261;foreach(var p in t.GetPixels32()){value=(value^p.r)*16777619;value=(value^p.g)*16777619;value=(value^p.b)*16777619;value=(value^p.a)*16777619;}return value;}}
  public static void Run(){try{InstallAndTest();File.WriteAllLines(Path.Combine(Root,"map-detail-verification.txt"),rows);EditorApplication.Exit(0);}catch(Exception e){rows.Add("FAIL "+e);File.WriteAllLines(Path.Combine(Root,"map-detail-verification.txt"),rows);Debug.LogException(e);EditorApplication.Exit(1);}}
  static void InstallAndTest(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/DoubleValley9x.unity");var data=MapDetailWindow.Ensure();data.Resolve();var b=data.terrain.definition.bounds;var originalTerrain=JsonUtility.ToJson(data.terrain.definition);var originalNodes=(Vector2[])data.roads.definition.nodes.Clone();data.areas.Clear();
   // Migrate the previous hand-positioned wheat regions; the author can replace or extend these boxes.
   data.areas.Add(new MapDetailRegions.Area{name="西原旧田区 · 不规则田块",bounds=new Rect(-43,-3,22,12),kind=MapDetailRegions.DetailKind.RuralMix,seed=217,greenFields=.60f});
   data.areas.Add(new MapDetailRegions.Area{name="南谷旧田区 · 土褐与浅黄",bounds=new Rect(-24.5f,-22,19,10),kind=MapDetailRegions.DetailKind.RuralMix,seed=1137,greenFields=.50f});
   data.areas.Add(new MapDetailRegions.Area{name="东原旧田区 · 混合乡村",bounds=new Rect(24,3.5f,20,13),kind=MapDetailRegions.DetailKind.RuralMix,seed=2741,greenFields=.62f});
   data.areas.Add(new MapDetailRegions.Area{name="南岸旧田区 · 村落与休耕地",bounds=new Rect(-.5f,-26,13,10),kind=MapDetailRegions.DetailKind.RuralMix,seed=4591,greenFields=.40f});
   Check(data.areas.Count==4,"previous hand-positioned field regions migrate to editable boxes");Check(data.areas.All(a=>MapDetailWindow.Clip(a.bounds,b)==a.bounds),"all initial boxes lie inside map");
   MapDetailBaker.Statistics stats,againStats;var a=MapDetailBaker.Generate(data,out stats,1024);var again=MapDetailBaker.Generate(data,out againStats,1024);Check(Fingerprint(a)==Fingerprint(again),"same areas and seeds produce identical pixel output");Check(stats.clippedFieldPixels==0,"complete fields remain clear of terrain and region masks without raster clipping");Check(stats.rejectedPlots>0,"fields touching obstacles are skipped as complete plots");Check(stats.fields>100,"irregular subdivision produces many small fields");Check(stats.diagonalEdges>stats.fields,"plots include diagonal polygon boundaries");Check(stats.roadAlignedEdges>stats.fields*2,"most field sides follow nearby road or its perpendicular");Check(stats.inkEdges>=stats.fields*3,"field boundaries receive layered irregular ink strokes");Check(stats.largestField>stats.smallestField*2,"field areas vary rather than forming equal grid cells");Check(stats.buildings>10&&stats.villages>=2,"rural boxes generate villages with buildings");Check(stats.palette[0]>0&&stats.palette[1]>0&&stats.palette[3]>0&&stats.palette[4]>0,"fields retain multiple muted yellow and brown tones");
   data.areas[0].seed++;MapDetailBaker.Statistics changedStats;var changed=MapDetailBaker.Generate(data,out changedStats,1024);Check(Fingerprint(a)!=Fingerprint(changed),"changing area seed changes generated layout");data.areas[0].seed--;
   var pixels=a.GetPixels32();int painted=0,outside=0;for(int y=0;y<a.height;y++)for(int x=0;x<a.width;x++){var p=pixels[y*a.width+x];if(p.a==0)continue;painted++;var point=new Vector2(b.xMin+(x+.5f)*b.width/a.width,b.yMin+(y+.5f)*b.height/a.height);if(!data.areas.Any(area=>area.bounds.Contains(point)))outside++;}Check(painted>10000,"generated overlay contains visible detail");Check(outside==0,"detail stays within manually specified regions");
   Check(originalTerrain==JsonUtility.ToJson(data.terrain.definition),"detail generation does not alter forests water mountains or terrain types");Check(originalNodes.SequenceEqual(data.roads.definition.nodes),"detail generation does not change road nodes");UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(again);UnityEngine.Object.DestroyImmediate(changed);
   var clipped=MapDetailWindow.Clip(new Rect(b.xMax-1,b.yMax-1,8,8),b);Check(clipped.width==1&&clipped.height==1,"selection crossing map edge is clipped");bool tooSmall=false;try{MapDetailWindow.AddArea(data,new Rect(0,0,.1f,.1f),MapDetailRegions.DetailKind.Farmland,1,1,.5f,1);}catch(InvalidOperationException){tooSmall=true;}Check(tooSmall&&data.areas.Count==4,"tiny drag selection is rejected without adding area");
   data.resolution=4096;MapDetailBaker.Bake(data);Check(data.bakedView!=null&&data.bakedView.sprite!=null,"generated detail is saved as a reusable baked sprite");Check(data.bakedView.GetComponents<Component>().Length==2,"detail layer has only transform and renderer");var old=GameObject.Find("麦田与草地 · 纯贴图装饰");Check(old==null||!old.GetComponent<SpriteRenderer>().enabled,"old giant single-colour wheat layer is replaced");
   data.resolution=1024;Undo.IncrementCurrentGroup();int undoGroup=Undo.GetCurrentGroup();MapDetailWindow.AddArea(data,new Rect(-20,-10,6,4),MapDetailRegions.DetailKind.Farmland,8911,1,.6f,1);Undo.FlushUndoRecordObjects();Undo.CollapseUndoOperations(undoGroup);Check(data.areas.Count==5&&data.areas.Last().bounds==new Rect(-20,-10,6,4),"drag-box add action records exact selected region and bakes preview");Undo.PerformUndo();Check(data.areas.Count==4,"undo restores previous area list");data.resolution=4096;MapDetailBaker.Bake(data);
   var overlay=data.GetComponent<StaffRoadOverlay>();overlay.Rebuild();Check(Mathf.Abs(data.roads.definition.roadWidth-.14f)<.00001f,"main road width reduced from 0.24 to 0.14");Check(Mathf.Abs(data.terrain.roadTerrainWidth-.14f)<.00001f,"visual road and traversable road widths agree");Check(overlay.BridgeCount>0,"bridges and crossing symbols remain after narrowing roads");
   bool narrow=false;foreach(var edge in data.roads.definition.connections){Vector2 p=(data.roads.definition.nodes[edge.a]+data.roads.definition.nodes[edge.b])*.5f;var d=(data.roads.definition.nodes[edge.b]-data.roads.definition.nodes[edge.a]).normalized;var n=new Vector2(-d.y,d.x);var centre=new RoadPoint(p.x,p.y);var side=p+n*.10f;if(data.terrain.TerrainAt(centre)==TerrainKind.Road&&data.terrain.TerrainAt(new RoadPoint(side.x,side.y))!=TerrainKind.Road){narrow=true;break;}}Check(narrow,"narrower road strip is reflected in actual terrain queries");
   var cartForPaths=data.GetComponent<StaffMapCartography>();cartForPaths.RefreshBridges();int routes=0;foreach(var bridge in cartForPaths.Bridges){var edge=data.roads.definition.connections[bridge.edge];Vector2 a0=data.roads.definition.nodes[edge.a],b0=data.roads.definition.nodes[edge.b],d0=b0-a0;Vector2 start=a0+d0*Mathf.Clamp01(Vector2.Dot(bridge.from-a0,d0)/d0.sqrMagnitude),end=a0+d0*Mathf.Clamp01(Vector2.Dot(bridge.to-a0,d0)/d0.sqrMagnitude);var access=TerrainAccess.Road|TerrainAccess.Ground|TerrainAccess.Grass|TerrainAccess.Forest;Check(data.terrain.CanTraverse(new RoadPoint(start.x,start.y),new RoadPoint(end.x,end.y),access),"bridge centreline remains physically passable "+routes);var path=LocalRoadAStar.Plan(data.terrain,access,new Vector3(start.x,start.y,0),new Vector3(end.x,end.y,0),.2f,30000);Check(path!=null,"A-star can cross narrowed bridge "+routes);routes++;}Check(routes>0,"bridge routes exercised");
   EditorUtility.SetDirty(data.roads.definition);EditorUtility.SetDirty(data);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();
   var cart=data.GetComponent<StaffMapCartography>();cart.ShowBakedBackground();Capture(data,b.center,b.height/2,3072,1920,"map-detail-overview.png");Vector2 focus=stats.villageCentres.Count>0?stats.villageCentres.OrderByDescending(p=>UnityEngine.Object.FindObjectsOfType<RecoveryPoint>().Min(city=>Vector2.Distance(p,city.transform.position))).First():new Vector2(-32,3);Capture(data,focus,4.375f,1600,1000,"map-detail-closeup.png");rows.Add("INFO fields="+stats.fields+" buildings="+stats.buildings+" villages="+stats.villages+" rejectedPlots="+stats.rejectedPlots+" clippedFieldPixels="+stats.clippedFieldPixels+" roadAlignedEdges="+stats.roadAlignedEdges+" inkEdges="+stats.inkEdges+" palette="+string.Join(",",stats.palette));
  }  static void Capture(MapDetailRegions data,Vector2 focus,float size,int width,int height,string name){var camera=UnityEngine.Object.FindObjectOfType<BattleWorld>().setup.mapCamera;var previousPosition=camera.transform.position;var previousRotation=camera.transform.rotation;float previousSize=camera.orthographicSize,previousAspect=camera.aspect;var target=camera.targetTexture;var rt=new RenderTexture(width,height,24);camera.targetTexture=rt;camera.transform.position=new Vector3(focus.x,focus.y,-20);camera.transform.rotation=Quaternion.identity;camera.orthographicSize=size;camera.aspect=width/(float)height;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(width,height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();File.WriteAllBytes(Path.Combine(Root,name),image.EncodeToPNG());RenderTexture.active=old;camera.targetTexture=target;camera.transform.position=previousPosition;camera.transform.rotation=previousRotation;camera.orthographicSize=previousSize;camera.aspect=previousAspect;UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(rt);}
 }
}

